#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <cstdlib>

using namespace std;

class DataReader {
private:
    istream& reader;
    istringstream st;
public:
    DataReader(istream& r) : reader(r) {}

    bool next(string& token) {
        while (!(st >> token)) {
            string s;
            if (!getline(reader, s)) return false;
            st.clear();
            st.str(s);
        }
        return true;
    }

    string nextToken() {
        string t;
        next(t);
        return t;
    }

    int nextInt() {
        return stoi(nextToken());
    }

    long long nextLong() {
        return stoll(nextToken());
    }

    vector<int> readIntArray(int n) {
        vector<int> result(n);
        for (int i = 0; i < n; i++) result[i] = nextInt();
        return result;
    }

    string nextLine() {
        string s;
        getline(reader, s);
        return s;
    }

    void solve(ostream& out);
};

string toYesNo(bool value) {
    return value ? "YES" : "NO";
}

void DataReader::solve(ostream& out) {
    int n = nextInt();
    int k = nextInt();

    string s = nextToken();

    vector<bool> used(n, false);

    function<bool(int)> dfs = [&](int u) -> bool {
        if (u < 0 || u >= n || used[u] || s[u] == '#') return false;
        if (s[u] == 'T') return true;
        used[u] = true;

        return dfs(u - k) || dfs(u + k);
    };

    out << toYesNo(dfs((int)s.find('G'))) << endl;
}

int main() {
    if (getenv("ONLINE_JUDGE") == nullptr) {
        ifstream in("input.txt");
        ofstream out("output.txt");
        DataReader(in).solve(out);
        out.flush();
    } else {
        DataReader(cin).solve(cout);
        cout.flush();
    }
    return 0;
}
